(()=>{if(matchMedia("(prefers-reduced-motion: reduce)").matches||!("IntersectionObserver"in window))return;const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("is-seen");observer.unobserve(entry.target)}})},{threshold:.12});document.querySelectorAll("[data-review-story]").forEach(card=>observer.observe(card))})();